'use strict';
let ledgerCursor=null,ledgerStarted=false;
const resultNumber=(n,suffix='%')=>Number.isFinite(n)?(n>=0?'+':'')+n.toFixed(2)+suffix:'—';
function contractSnapshotHTML(s){
 if(!s||s.state!=='Observed')return `<p>${esc(s?.state||'Not recorded')}</p>`;
 return `<p>${stamp(s.checkedAt)}${s.resolved?' · resolved':s.closed?' · closed':''}</p><div class="track-metrics">${(s.outcomes||[]).map(o=>`<span><b>${esc(o.label)} ${Number.isFinite(o.price)?(o.price*100).toFixed(1)+'¢':'—'}</b><small>Bid ${Number.isFinite(o.bid)?(o.bid*100).toFixed(1)+'¢':'—'} / Ask ${Number.isFinite(o.ask)?(o.ask*100).toFixed(1)+'¢':'—'} · spread ${Number.isFinite(o.spread)?(o.spread*100).toFixed(1)+'¢':'—'}</small></span>`).join('')}</div>`;
}
function investigationResultHTML(r){
 if(r.type==='contract')return `<h4>At publication</h4>${contractSnapshotHTML(r.original)}<h4>Latest provider check</h4>${contractSnapshotHTML(r.current)}<p>${(r.current?.outcomes||[]).map(o=>{const before=r.original?.outcomes?.find(v=>v.label===o.label);return Number.isFinite(before?.price)&&Number.isFinite(o.price)?esc(o.label)+': '+resultNumber((o.price-before.price)*100,' pp since publication'):''}).filter(Boolean).join(' · ')}</p><details><summary>Original resolution rules</summary><p class="preserve-lines">${esc(r.original?.rules||'No original rules snapshot was recorded.')}</p>${researchLink(r.original?.resolutionSource,'Resolution source')}</details><p class="muted">${esc(r.method)}</p>`;
 return `<p><b>${esc(r.state||r.error||'Unavailable')}</b>${r.entry?' · Entry '+date(r.entry):''}${r.end?' · End '+date(r.end):''}</p>${r.state==='Completed'?`<div class="track-metrics"><span><small>20-session net return</small><b class="${r.netReturn>=0?'gain':'loss'}">${resultNumber(r.netReturn)}</b></span><span><small>vs S&P 500 proxy</small><b>${resultNumber(r.excess,' pp')}</b></span><span><small>25 bps / side stress</small><b>${resultNumber(r.costStressReturn)}</b></span><span><small>Worst closing drawdown</small><b>${resultNumber(r.drawdown)}</b></span></div>`:''}<p class="muted">${esc(r.method||'Only new evidence-backed stock findings marked supported at publication enter the prospective results. Wait, rejected and unverified cases remain in the archive.')}</p>`;
}
async function loadInvestigationLedger(){
 const button=$('#ledgerMore');button.disabled=true;button.textContent='Loading history…';
 try{const d=await getLiveJSON('/api/research/ledger'+(ledgerCursor?'?cursor='+encodeURIComponent(ledgerCursor):''));if(d.error)throw Error(d.error);
 $('#researchLedgerRows').insertAdjacentHTML('beforeend',(d.items||[]).map(a=>`<details class="ledger-entry"><summary>${esc(a.target)} · ${esc(a.phase==='challenge'?'Review':'Finding')} · ${esc(investigationLabel[a.verdict]||a.verdict)} · ${stamp(a.publishedAt)}</summary>${investigationCard(a,null)}</details>`).join('')||'<p>No archived findings yet.</p>');
 ledgerStarted=true;ledgerCursor=d.cursor;button.hidden=!ledgerCursor;
 }catch{button.textContent='Retry history';return}finally{button.disabled=false}button.textContent='Next archive page';
}
async function refreshAccountability(){
 const reports=await Promise.allSettled([getLiveJSON('/api/research/coverage'),getLiveJSON('/api/research/investigation-scorecard')]);
 const coverage=reports[0].status==='fulfilled'?reports[0].value:null;
 for(const el of document.querySelectorAll('[data-coverage-report]'))el.innerHTML=coverage?`<summary>Data coverage · ${coverage.stale?'Needs refresh':'Recently checked'} · ${coverage.rows} loaded transactions</summary><p>${coverage.people} households · ${coverage.linked}/${coverage.rows} source-linked · ${coverage.dated}/${coverage.rows} disclosure-dated${coverage.skipped!==null?' · '+coverage.skipped+' excluded by provider parsing':''}</p><p>Feed checked ${coverage.checkedAt?stamp(coverage.checkedAt):'not recorded'} · latest loaded disclosure ${coverage.last?date(coverage.last):'unknown'}</p><p>${esc(coverage.coverage)}</p><p>${esc(coverage.method)}</p><p>${researchLink('https://disclosures-clerk.house.gov/FinancialDisclosure','House filings')} · ${researchLink('https://efdsearch.senate.gov/search/','Senate filings')}</p>`:'<summary>Data coverage unavailable · retry later</summary>';
 const raw=reports[1].status==='fulfilled'?reports[1].value:null,d=raw?.value||raw,el=$('#investigationScorecard');
 if(!d?.summary){el.textContent='Results unavailable. No performance is assumed.';return}
 const s=d.summary;el.innerHTML=`<h3>Investigations · measured results</h3><div class="track-metrics"><span><small>Completed / registered</small><b>${s.completed} / ${d.registered}</b></span><span><small>Winners / losers / flat</small><b>${s.winners} / ${s.losers} / ${s.flat}</b></span><span><small>Mean net return</small><b>${resultNumber(s.meanNet)}</b></span><span><small>vs S&P 500 proxy</small><b>${resultNumber(s.meanExcess,' pp')}</b></span></div><p class="muted">${esc(d.method)}${raw?.stale?' Saved results · refresh failed.':''}</p><details><summary>Every measured case in this window</summary>${(d.rows||[]).map(r=>`<div class="ledger-entry"><b>${esc(r.symbol||'Stock')} · ${esc(r.title)}</b>${investigationResultHTML(r)}</div>`).join('')||'<p>No eligible findings registered yet. Results begin with future supported publications.</p>'}</details>`;
}
if(typeof window!=='undefined'){
 const daily=$('#dailyResearchActivity');if(daily)daily.insertAdjacentHTML('afterend','<section class="accountability-panel"><div id="investigationScorecard">Checking measured results…</div><details id="researchLedger"><summary>Permanent research archive · all verdicts and reviews</summary><p class="muted">Includes failed verification, waits, rejections and later challenges. Archive pages are sorted by date within each page. These are research records, not trade recommendations.</p><div id="researchLedgerRows"></div><button id="ledgerMore">Load archive</button></details></section>');
 const sources=$('#sourcesView');if(sources)sources.insertAdjacentHTML('afterbegin','<details class="accountability-panel" data-coverage-report><summary>Checking source coverage…</summary></details>');
 const home=$('#homeResearchActivity');if(home)home.insertAdjacentHTML('beforebegin','<details class="coverage-strip" data-coverage-report><summary>Checking source coverage…</summary></details>');
 $('#researchLedger').addEventListener('toggle',()=>{if($('#researchLedger').open&&!ledgerStarted)loadInvestigationLedger()});$('#ledgerMore').onclick=loadInvestigationLedger;
 document.addEventListener('click',async e=>{const b=e.target.closest('[data-investigation-result]');if(!b)return;b.disabled=true;const box=b.nextElementSibling;box.textContent='Checking recorded results…';try{box.innerHTML=investigationResultHTML(await getLiveJSON('/api/research/investigation-result?id='+b.dataset.investigationResult))}catch{box.textContent='Results unavailable; retry shortly.'}finally{b.disabled=false}});
 refreshAccountability();setInterval(()=>{if(!document.hidden)refreshAccountability()},15*60000);
}
